files.billing:
from policy import eligible

def quote(subtotal, threshold, percent):
    if eligible(subtotal, threshold):
        return subtotal - subtotal * percent // 100
    return subtotal

files.inventory:
from quantities import totals

def can_reserve(stock, lines):
    return all(qty <= stock.get(sku, 0) for sku, qty in totals(lines).items())

reference.quantities:
def totals(lines):
    result = {}
    for sku, qty in lines:
        result[sku] = result.get(sku, 0) + qty
    return result

files.cache:
from clock_rules import valid

def get_cached(value, created, ttl, now, fallback=None):
    return value if valid(created, ttl, now) else fallback

files.catalog:
from text_keys import tag_key

def clean_tags(tags):
    result, seen = [], set()
    for raw in tags:
        tag = raw.strip()
        key = tag_key(tag)
        if tag and key not in seen:
            result.append(tag)
            seen.add(key)
    return result

files.workflow:
from states import ALLOWED, is_terminal

def can_move(current, target):
    if is_terminal(current):
        return current == target
    return target in ALLOWED.get(current, ())

reference.states:
ALLOWED = {
    "open": ("paid", "cancelled"), "paid": ("shipped", "refunded"),
    "shipped": ("delivered",), "refunded": ("paid",), "cancelled": ("open",),
}
def is_terminal(state):
    return state in {"delivered", "refunded", "cancelled"}

files.routing:
from route_aliases import route_name

def resolve(key, routes, aliases, default=None):
    name = route_name(key, routes, aliases)
    return routes.get(name, default)

reference.route_aliases:
def route_name(key, routes, aliases):
    if key in routes:
        return key
    return aliases.get(key, key)

reference.ledger:
def approve_one(requested, remaining):
    approved = min(requested, remaining)
    return approved, remaining - approved

files.schedule:
from windows import contains

def allowed(minute, start, end):
    return contains(minute, start, end)

reference.windows:
def contains(minute, start, end):
    if end < start:
        return minute >= start or minute < end
    return start <= minute < end
